// Mimic Extract Telegram Meta output from a plain webhook body.
const b = $input.item.json.body || $input.item.json;
const d = new Date();
const pad = n => String(n).padStart(2, '0');
const submissionDate = `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
return { json: {
  telegram_user: b.telegram_user || 'Peter (demo)',
  file_unique_id: b.file_unique_id || ('demo-' + Date.now()),
  telegram_message_id: b.telegram_message_id || 0,
  submission_date: submissionDate,
  submission_iso: d.toISOString(),
  caption: b.caption || '',
  image_url: b.image_url,
  go_key: b.go_key || ''
}};

// VERBATIM from W2 'Photo to Base64' (production workflow).
const bin = $input.item.binary || {};
const key = bin.data ? 'data' : Object.keys(bin)[0];
if (!key || !bin[key]) throw new Error('Telegram file binary missing');
const buffer = await this.helpers.getBinaryDataBuffer(0, key);
const b64data = buffer.toString('base64');
if (!b64data || b64data.length < 100) throw new Error('Empty image buffer from Telegram file');
const mime = bin[key].mimeType || 'image/jpeg';
const prompt = 'You are a receipt OCR extractor. Read this receipt photo and reply with ONLY a compact JSON object, no markdown, no extra text. Keys and rules: merchant (store name, string, or Unknown), amount (grand total as a plain number, no currency symbols), currency (3-letter code, default PHP), receipt_date (YYYY-MM-DD as printed, or empty string if not visible), category (one of: Food, Transport, Office, Utilities, Healthcare, Shopping, Other), items (array of up to 8 short item names), confidence (0 to 1 self-score), notes (one short sentence or empty string).';
return {
  json: { image_b64: b64data, mime_type: mime, gemini_prompt: prompt },
  binary: $input.item.binary
};

// Build an OpenAI-compatible vision request for the opencode Go endpoint.
// The API key arrives via the webhook payload and is NEVER persisted.
let meta = {};
try { meta = $('Build Demo Meta').item.json; } catch (e) { meta = $('Build Demo Meta').first().json; }
const j = $input.item.json;
const body = {
  model: 'glm-5.3-flash',
  messages: [{ role: 'user', content: [
    { type: 'text', text: j.gemini_prompt },
    { type: 'image_url', image_url: { url: 'data:' + j.mime_type + ';base64,' + j.image_b64 } }
  ]}],
  temperature: 0.1, max_tokens: 400
};
return { json: {
  vision_url: 'https://opencode.ai/zen/go/v1/chat/completions',
  session_header: 'demo-receipt-vision-01',
  body_string: JSON.stringify(body)
}};

// Demo variant of W2 'Parse Receipt JSON': reads an OpenAI-compatible
// reply (choices[0].message.content) with Gemini candidates[] fallback,
// then applies the SAME validation/normalization as production.
function get(obj, path, fb) { try { let cur = obj; for (const k of path) cur = cur?.[k]; return cur ?? fb; } catch (e) { return fb; } }
const resp = $input.item.json;
let raw = get(resp, ['choices', 0, 'message', 'content'], '');
if (!raw) raw = get(resp, ['candidates', 0, 'content', 'parts', 0, 'text'], '');
if (Array.isArray(raw)) raw = raw.map(p => p.text || '').join('');
raw = String(raw || '').replace(/```[a-zA-Z]*\\n?/g, '').replace(/```/g, '').trim();
const m = raw.match(/\\{[\\s\\S]*\\}/);
let data = {};
try { data = JSON.parse(m ? m[0] : raw); } catch (e) { data = {}; }
let meta = {};
try { meta = $('Build Demo Meta').item.json; } catch (e) { meta = {}; }
let amount = Number(String(data.amount ?? '').replace(/[^0-9.\\-]/g, ''));
if (!isFinite(amount)) amount = 0;
let currency = String(data.currency || 'PHP').toUpperCase().replace(/[^A-Z]/g, '').slice(0, 3) || 'PHP';
let receiptDate = String(data.receipt_date || '');
if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(receiptDate)) receiptDate = meta.submission_date || '';
let confidence = Number(data.confidence);
if (!isFinite(confidence)) confidence = 0;
if (confidence > 1 && confidence <= 100) confidence = confidence / 100;
confidence = Math.min(1, Math.max(0, confidence));
const merchant = String(data.merchant || '').trim() || 'Unknown';
const minConf = 0.6;
const needsReview = (!merchant || merchant === 'Unknown' || amount <= 0 || confidence < minConf);
const items = Array.isArray(data.items) ? data.items.map(String).slice(0, 8).join('; ') : '';
const category = String(data.category || 'Other');
return { json: {
  submission_date: meta.submission_date || '',
  telegram_user: meta.telegram_user || '',
  file_unique_id: meta.file_unique_id || '',
  merchant, amount, currency, receipt_date: receiptDate,
  category, items,
  confidence: Math.round(confidence * 100) / 100,
  needs_review: needsReview,
  notes: String(data.notes || '').slice(0, 300),
  source_image: meta.image_url || '',
  processed_at: new Date().toISOString()
}};
